	and MGM_G11(ENABLE_D_AND_GB_AND_SB,SB_delay,MGM_W5);


	buf MGM_G12(ENABLE_RB,RB_delay);


	not MGM_G13(MGM_W6,D_delay);


	and MGM_G14(ENABLE_NOT_D_AND_GB,GB_delay,MGM_W6);


	and MGM_G15(ENABLE_D_AND_GB,GB_delay,D_delay);


