	and MGM_G2(MGM_W1,RB_delay,MGM_W0);


	and MGM_G3(ENABLE_NOT_D_AND_RB_AND_SB,SB_delay,MGM_W1);


	and MGM_G4(MGM_W2,RB_delay,D_delay);


	and MGM_G5(ENABLE_D_AND_RB_AND_SB,SB_delay,MGM_W2);


	buf MGM_G6(ENABLE_SB,SB_delay);


	not MGM_G7(MGM_W3,D_delay);


	not MGM_G8(MGM_W4,G_delay);


	and MGM_G9(MGM_W5,MGM_W4,MGM_W3);


	and MGM_G10(ENABLE_NOT_D_AND_NOT_G_AND_SB,SB_delay,MGM_W5);


	not MGM_G11(MGM_W6,G_delay);


	and MGM_G12(MGM_W7,MGM_W6,D_delay);


	and MGM_G13(ENABLE_D_AND_NOT_G_AND_SB,SB_delay,MGM_W7);


	buf MGM_G14(ENABLE_RB,RB_delay);


	not MGM_G15(MGM_W8,D_delay);


	not MGM_G16(MGM_W9,G_delay);


	and MGM_G17(ENABLE_NOT_D_AND_NOT_G,MGM_W9,MGM_W8);


	not MGM_G18(MGM_W10,G_delay);


	and MGM_G19(ENABLE_D_AND_NOT_G,MGM_W10,D_delay);


	not MGM_G20(MGM_W11,D_delay);


	not MGM_G21(MGM_W12,G_delay);


	and MGM_G22(MGM_W13,MGM_W12,MGM_W11);


	and MGM_G23(ENABLE_NOT_D_AND_NOT_G_AND_RB,RB_delay,MGM_W13);


	not MGM_G24(MGM_W14,G_delay);


	and MGM_G25(MGM_W15,MGM_W14,D_delay);


	and MGM_G26(ENABLE_D_AND_NOT_G_AND_RB,RB_delay,MGM_W15);


	// spec_gates_end



   specify

	// specify_block_begin 

	// comb arc D --> Q
	 (D => Q) = (1.0,1.0);

	// seq arc G --> Q
	(posedge G => (Q : D))  = (1.0,1.0);

	// seq arc RB --> Q
	(RB => Q)  = (1.0,1.0);

	// seq arc SB --> Q
	(SB => Q)  = (1.0,1.0);

	// comb arc D --> QB
	 (D => QB) = (1.0,1.0);

	// seq arc G --> QB
	(posedge G => (QB : D))  = (1.0,1.0);

	// seq arc RB --> QB
	(RB => QB)  = (1.0,1.0);

	// seq arc SB --> QB
	(SB => QB)  = (1.0,1.0);

	// setuphold D- G-HL
	$setuphold(negedge G &&& (ENABLE_RB_AND_SB === 1'b1),
		posedge D &&& (ENABLE_RB_AND_SB === 1'b1),
		1.0,1.0,notifier,,,G_delay,D_delay);

	// setuphold D- G-HL
	$setuphold(negedge G &&& (ENABLE_RB_AND_SB === 1'b1),
		negedge D &&& (ENABLE_RB_AND_SB === 1'b1),
		1.0,1.0,notifier,,,G_delay,D_delay);

	$width(posedge G &&& (ENABLE_NOT_D_AND_RB_AND_SB === 1'b1)
		,1.0,0,notifier);

	$width(posedge G &&& (ENABLE_D_AND_RB_AND_SB === 1'b1)
		,1.0,0,notifier);

	// recrem RB-G-negedge
	$recrem(posedge RB &&& (ENABLE_SB === 1'b1),
		negedge G &&& (ENABLE_SB === 1'b1),
		1.0,1.0,notifier,,,RB_delay,G_delay);

	$width(negedge RB &&& (ENABLE_NOT_D_AND_NOT_G_AND_SB === 1'b1)
		,1.0,0,notifier);

	$width(negedge RB &&& (ENABLE_D_AND_NOT_G_AND_SB === 1'b1)
		,1.0,0,notifier);

	// recrem SB-G-negedge
	$recrem(posedge SB &&& (ENABLE_RB === 1'b1),
		negedge G &&& (ENABLE_RB === 1'b1),
		1.0,1.0,notifier,,,SB_delay,G_delay);

	// setuphold SB- RB-LH
	$setuphold(posedge RB &&& (ENABLE_NOT_D_AND_NOT_G === 1'b1),
		posedge SB &&& (ENABLE_NOT_D_AND_NOT_G === 1'b1),
		1.0,1.0,notifier,,,RB_delay,SB_delay);

	// setuphold SB- RB-LH
	$setuphold(posedge RB &&& (ENABLE_D_AND_NOT_G === 1'b1),
		posedge SB &&& (ENABLE_D_AND_NOT_G === 1'b1),
		1.0,1.0,notifier,,,RB_delay,SB_delay);

	$width(negedge SB &&& (ENABLE_NOT_D_AND_NOT_G_AND_RB === 1'b1)
		,1.0,0,notifier);

	$width(negedge SB &&& (ENABLE_D_AND_NOT_G_AND_RB === 1'b1)
		,1.0,0,notifier);

	// mpw G_lh 
	$width(posedge G,1.0,0,notifier);

	// mpw RB_hl 
	$width(negedge RB,1.0,0,notifier);

	// mpw SB_hl 
	$width(negedge SB,1.0,0,notifier);

	// specify_block_end 

   endspecify

   `endif 

endmodule
`endcelldefine

