`celldefine
module SDFCM1HM( Q, QB, CKB, D, SD, SE , VDD, VSS);
inout VDD;
supply1 VDD;
inout VSS;
supply0 VSS;
input CKB, D, SD, SE;
output Q, QB;
reg notifier;

   `ifdef FUNCTIONAL  //  functional //

	SDFCM1HM_func SDFCM1HM_behav_inst(.Q(Q),.QB(QB),.CKB(CKB),.D(D),.SD(SD),.SE(SE),.notifier(notifier),.VDD(VDD),.VSS(VSS));

   `else

	wire CKB_delay ;

	wire D_delay ;

	wire SD_delay ;

	wire SE_delay ;

	SDFCM1HM_func SDFCM1HM_inst(.Q(Q),.QB(QB),.CKB(CKB_delay),.D(D_delay),.SD(SD_delay),.SE(SE_delay),.notifier(notifier),.VDD(VDD),.VSS(VSS));


	// spec_gates_begin


	not MGM_G0(MGM_W0,D_delay);


	not MGM_G1(MGM_W1,SD_delay);


	and MGM_G2(MGM_W2,MGM_W1,MGM_W0);


	not MGM_G3(MGM_W3,SE_delay);


	and MGM_G4(ENABLE_NOT_D_AND_NOT_SD_AND_NOT_SE,MGM_W3,MGM_W2);


	not MGM_G5(MGM_W4,D_delay);


	not MGM_G6(MGM_W5,SD_delay);


	and MGM_G7(MGM_W6,MGM_W5,MGM_W4);


	and MGM_G8(ENABLE_NOT_D_AND_NOT_SD_AND_SE,SE_delay,MGM_W6);


	not MGM_G9(MGM_W7,D_delay);


	and MGM_G10(MGM_W8,SD_delay,MGM_W7);


	not MGM_G11(MGM_W9,SE_delay);


	and MGM_G12(ENABLE_NOT_D_AND_SD_AND_NOT_SE,MGM_W9,MGM_W8);


	not MGM_G13(MGM_W10,D_delay);


	and MGM_G14(MGM_W11,SD_delay,MGM_W10);


	and MGM_G15(ENABLE_NOT_D_AND_SD_AND_SE,SE_delay,MGM_W11);


	not MGM_G16(MGM_W12,SD_delay);


	and MGM_G17(MGM_W13,MGM_W12,D_delay);


	not MGM_G18(MGM_W14,SE_delay);


	and MGM_G19(ENABLE_D_AND_NOT_SD_AND_NOT_SE,MGM_W14,MGM_W13);


	not MGM_G20(MGM_W15,SD_delay);


	and MGM_G21(MGM_W16,MGM_W15,D_delay);


	and MGM_G22(ENABLE_D_AND_NOT_SD_AND_SE,SE_delay,MGM_W16);


	and MGM_G23(MGM_W17,SD_delay,D_delay);


	not MGM_G24(MGM_W18,SE_delay);


